insert into public.recipes (id, status, cover_image, prep_minutes, cook_minutes, servings, video_url, family_id, variant_label, variant_image, related_post_ids) values ('recipe-makowiec', 'published', 'https://kdrbtwwhmzszzukcffsu.supabase.co/storage/v1/object/public/recipe-media/recipes/recipe-makowiec/53f5d3bc-8156-4441-a67e-83ddff7184b9.webp', 45, 50, 12, null, null, '{}'::jsonb, '', array['post-makowiec-technik', 'post-wigilia', 'post-faworki-technik', 'post-ersatzprodukte-de', 'post-polenladen']::text[]) on conflict (id) do update set status = excluded.status, cover_image = excluded.cover_image, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes, servings = excluded.servings, video_url = excluded.video_url, family_id = excluded.family_id, variant_label = excluded.variant_label, variant_image = excluded.variant_image, related_post_ids = excluded.related_post_ids, updated_at = now();
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-makowiec', 'de', 'Makowiec', 'makowiec', 'Gerollter Hefekuchen mit dichter Mohnfüllung, klassisch zur Wigilia gebacken, außen goldbraun und innen in jeder Scheibe saftig mohnig.', '[{"text":"Mohn mit heißer Milch aufquellen lassen, vollständig abkühlen lassen und dann mit Zucker, Butter und Ei zu einer streichfähigen Masse verrühren.","tip":"Die Masse ist richtig, wenn sie schwer vom Löffel fällt und nicht bröckelt, mehr zur Konsistenz zeigt der [Makowiec-Technik-Guide](/de/blog/makowiec-technik)."},{"text":"Hefeteig aus Mehl, Milch, Butter, Zucker, Ei und Hefe kneten und an einem warmen Ort gehen lassen, bis er sich sichtbar verdoppelt hat.","tip":"Ein Teig, der zu kühl steht, braucht deutlich länger, stelle die Schüssel daher am besten in die Nähe der Heizung oder in den leicht vorgewärmten, ausgeschalteten Ofen."},{"text":"Den Teig zu einem Rechteck ausrollen, die Mohnmasse gleichmäßig verteilen und dabei an den Rändern etwas Platz lassen, dann fest von der langen Seite aufrollen und mit der Nahtstelle nach unten auf das Blech legen.","tip":"Ein zu dünn ausgerollter Teig reißt beim Rollen leicht ein, deshalb lieber etwas dicker lassen und die Rolle vorsichtig, aber bestimmt schließen."},{"text":"Mit verquirltem Ei bestreichen und bei mittlerer Hitze goldbraun backen, dann vollständig auskühlen lassen, bevor der Kuchen in Scheiben geschnitten wird.","tip":"Bei zu hoher Hitze bräunt die Oberfläche, während der Kern innen noch roh bleibt, eine Stäbchenprobe mitten im Teigteil zeigt zuverlässig, ob die Rolle durch ist."}]'::jsonb, 'Makowiec, gerollt, mohnig, geduldig gebacken und ein fester Programmpunkt am Heiligabend. Mohn erreichte Polen im Mittelalter über Handelswege aus dem Schwarzmeerraum, unter anderem über Lublin, wo genuesische und venezianische Kaufleute exotische Waren wie Mohn, Pfeffer und Safran ins Landesinnere brachten. In der slawischen Volksüberlieferung galt Mohn wegen seiner unzähligen kleinen Samen als Zeichen von Fruchtbarkeit und Überfluss, außerdem schrieb man ihm eine Verbindung zwischen den Lebenden und den Verstorbenen zu, weshalb Mohngerichte lange auch zu Trauerfeiern gehörten. Die Idee, Mohn zu einer Rolle aus Hefeteig zu verarbeiten, wird oft mit einer Anekdote verknüpft: 1681 soll der Hofbäcker von König Jan III. Sobieski eine riesige Mohnstrudel mit dem Bildnis der Königin Marysieńka gebacken haben, so groß und schwer, dass sie mit einem Schlitten transportiert werden musste. Der heutige Makowiec in seiner bekannten Form etablierte sich vor allem im 18. und 19. Jahrhundert, als Zucker und Bäckerhefe leichter verfügbar wurden, in manchen Regionen setzte er sich sogar erst nach dem Zweiten Weltkrieg durch, mitgebracht von Umsiedlern aus den polnischen Ostgebieten. Bis heute bleibt Makowiec eine eigenständige Form neben anderen Mohngerichten der Wigilia wie der Weizen-Mohn-Süßspeise [Kutia](/de/rezepte/kutia), dort schwimmen ganze Weizenkörner in einer Mohn-Honig-Mischung, hier trägt ein gerollter Hefeteig eine dichte, streichfähige Mohnmasse.

## Einkaufen und kochen

Für Teig und Füllung brauchst du blauen Mohn, am besten frisch gemahlen oder fertig gemahlen aus dem [Polenladen](/de/blog/polenladen-einkaufen), dazu Mehl, Frischhefe, Milch, Butter, Eier und Zucker, Rosinen sind optional. Achte beim Mohn auf ein möglichst frisches Mahldatum, denn gemahlener Mohn verliert nach einigen Wochen an Aroma und wird schneller ranzig. Wer die Feuchtigkeit der Masse noch nicht einschätzen kann, findet ausführliche Hinweise im [Makowiec-Technik-Guide](/de/blog/makowiec-technik), der auch den Platz des Kuchens im [Wigilia-Speiseplan](/de/blog/wigilia-speiseplan) einordnet.

Die Mohnmasse muss vor dem Füllen streichfähig, aber nicht flüssig sein, sonst läuft sie beim Rollen aus dem Teig heraus. Der Hefeteig sollte weich und elastisch bleiben und wirklich Zeit zum Gehen bekommen, in einem zu kalten Raum verdoppelt sich die Gehzeit locker. Beim Ausrollen lohnt sich ein Randabstand von etwa zwei Zentimetern, damit beim Rollen keine Masse seitlich austritt, und die fertige Rolle kommt mit der Nahtstelle nach unten aufs Blech. Backe bei mittlerer Hitze, denn ein zu heißer Ofen bräunt die Kruste, während der Kern innen roh bleibt, und schneide erst, wenn der Kuchen vollständig ausgekühlt ist, sonst zerfällt die Spirale.

In Deutschland rettet ein früher Backtag oft den 24. Dezember: Der Duft von frisch gebackenem Mohnkuchen zieht schon am 23. durch die Wohnung, während am eigentlichen Feiertag nur noch angerichtet werden muss. Fertiger Makowiec aus dem Regal ist für viele Familien ein Notbehelf für stressige Jahre, kein Ersatz für die eigene Technik, wie der [Makowiec-Technik-Guide](/de/blog/makowiec-technik) im Detail zeigt. Kinder dürfen beim Mohnrühren und beim Bestreichen mit Ei helfen, das Rollen und der heiße Ofen bleiben Erwachsenensache.

## Am Tisch

Serviere Makowiec in Scheiben, oft mit etwas Puderzucker bestäubt, klassisch als süßer Abschluss nach klarem [Barszcz](/de/rezepte/barszcz-czerwony) mit [Uszka](/de/rezepte/uszka). Am Vortag gebacken lässt er sich am 24. Dezember einfach nur noch aufschneiden, das entlastet den ohnehin vollen Tag. Wer zwei Süßspeisen nebeneinander servieren möchte, stellt Makowiec neben den cremigen [Sernik](/de/rezepte/sernik) auf den Tisch, beide ergänzen sich gut, weil der eine mohnig und trocken bleibt, der andere cremig und feucht.

Eine zu trockene Mohnmasse lässt sich schlecht verstreichen und reißt beim Rollen, während eine zu feuchte Masse den Teig von innen aufweicht. Zu viel Mehl im Teig macht die Krume trocken und schwer, ein zu heißer Ofen bräunt die Außenseite, bevor der Kern durchgebacken ist. Wer zu früh anschneidet, quetscht die noch warme Spirale platt, deshalb lohnt sich Geduld bis zum vollständigen Auskühlen. Beim Füllen sollte immer ein Rand frei bleiben, sonst quillt die Masse beim Rollen seitlich heraus.

Mit Rosinen oder einem dünnen Zuckerguss verändert sich der Charakter nur leicht, kleinere Rollen eignen sich gut, wenn mehrere Sorten Festtagsgebäck auf den Tisch sollen. Ganz anderes Festtagsgebäck sind die knusprigen [Faworki](/de/rezepte/faworki), deren Technik der [Faworki-Technik-Guide](/de/blog/faworki-technik) erklärt. Der cremige [Sernik](/de/rezepte/sernik) bleibt trotz gemeinsamer Festtagsrolle ein komplett anderes Gericht, ebenso der Hefegugelhupf [Babka](/de/rezepte/babka) und der würzige Honigkuchen [Piernik](/de/rezepte/piernik). Wer Mohn lieber in Suppenform mag, findet ihn in der Weizen-Mohn-Süßspeise [Kutia](/de/rezepte/kutia).', 'Makowiec Rezept | Mohnkuchen gerollt | Alemniam', 'Makowiec Schritt für Schritt backen, der polnische Mohnkuchen mit Einkaufstipps für Deutschland und Einordnung in den Wigilia-Speiseplan.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-makowiec', 'pl', 'Makowiec', 'makowiec', 'Zwinięta rolada drożdżowa z gęstym, aromatycznym nadzieniem makowym, tradycyjnie pieczona na Wigilię, złota z zewnątrz i wilgotna w każdym kawałku w środku.', '[{"text":"Zalej mak gorącym mlekiem, zostaw do całkowitego wystudzenia, a potem wymieszaj z cukrem, masłem i jajkiem na gładką, smarowną masę.","tip":"Masa jest gotowa, gdy ciężko opada z łyżki i się nie kruszy, więcej o konsystencji znajdziesz w [technice makowca](/pl/blog/makowiec-technika)."},{"text":"Wyrób ciasto drożdżowe z mąki, mleka, masła, cukru, jajka i drożdży, a potem odstaw je w ciepłe miejsce, aż widocznie podwoi swoją objętość.","tip":"Ciasto stojące w chłodnym miejscu rośnie znacznie dłużej, dlatego najlepiej postaw miskę blisko kaloryfera albo w lekko podgrzanym, wyłączonym piekarniku."},{"text":"Rozwałkuj ciasto na prostokąt, rozsmaruj masę makową równomiernie, zostawiając zapas od brzegów, a następnie zwiń mocno od dłuższej strony i ułóż roladę łączeniem do dołu na blasze.","tip":"Za cienko rozwałkowane ciasto łatwo pęka przy zwijaniu, więc lepiej zostawić je odrobinę grubsze i zwijać rolkę delikatnie, ale zdecydowanie."},{"text":"Posmaruj roztrzepanym jajkiem i piecz w średniej temperaturze na złoty kolor, a potem ostudź całkowicie, zanim pokroisz ciasto na kawałki.","tip":"Za wysoka temperatura przypala wierzch, a środek zostaje surowy, patyczek wbity w środkową część ciasta wiarygodnie pokaże, czy rolada jest upieczona."}]'::jsonb, 'Makowiec, zwinięty, makowy, cierpliwie pieczony i stały punkt kolacji wigilijnej. Mak trafił do Polski w średniowieczu szlakami handlowymi z basenu Morza Czarnego, między innymi przez Lublin, dokąd genueńscy i wenecjańscy kupcy przywozili egzotyczne towary, takie jak mak, pieprz czy szafran. W słowiańskich wierzeniach ludowych mak, ze względu na tysiące drobnych ziaren w makówce, symbolizował płodność i dostatek, a przypisywano mu też moc łączenia świata żywych ze światem umarłych, dlatego potrawy z makiem długo towarzyszyły również stypom. Pomysł zawinięcia maku w roladę z ciasta drożdżowego wiąże się często z anegdotą o dworze Jana III Sobieskiego: w 1681 roku nadworny piekarz miał upiec ogromną struclę z wizerunkiem królowej Marysieńki, tak wielką i ciężką, że do przewiezienia potrzebne były sanie. Dzisiejszy makowiec w znanej formie utrwalił się głównie w XVIII i XIX wieku, gdy cukier i drożdże piekarskie stały się łatwiej dostępne, w niektórych regionach zadomowił się nawet dopiero po drugiej wojnie światowej, przywieziony przez przesiedleńców z terenów wschodnich. Do dziś makowiec zostaje osobną formą wśród innych wigilijnych dań z makiem, takich jak pszenna [kutia](/pl/rezepte/kutia), tam całe ziarna pszenicy pływają w mieszance maku i miodu, tutaj zwinięte ciasto drożdżowe niesie gęstą, smarowną masę makową.

## Zakupy i gotowanie

Na ciasto i masę potrzebujesz niebieskiego maku, najlepiej świeżo zmielonego albo gotowego z [polskiego sklepu](/pl/blog/sklep-polski-zakupy), do tego mąki, świeżych drożdży, mleka, masła, jajek i cukru, rodzynki są opcjonalne. Przy maku zwróć uwagę na możliwie świeżą datę zmielenia, bo zmielony mak po kilku tygodniach traci aromat i szybciej jełczeje. Kto nie jest jeszcze pewny właściwej konsystencji masy, znajdzie dokładne wskazówki w [technice makowca](/pl/blog/makowiec-technika), który pokazuje też miejsce ciasta w [menu wigilijnym](/pl/blog/menu-wigilijne).

Masa makowa musi być przed nadzieniem smarowna, ale nie płynna, inaczej wypłynie z ciasta podczas zwijania. Ciasto drożdżowe powinno zostać miękkie i elastyczne i naprawdę dostać czas na wyrastanie, bo w chłodnym pomieszczeniu ten czas z łatwością się podwaja. Przy wałkowaniu warto zostawić około dwóch centymetrów zapasu od brzegu, żeby masa nie wypłynęła bokiem podczas zwijania, a gotową roladę układa się na blasze łączeniem do dołu. Piecz w średniej temperaturze, bo za gorący piekarnik przypala skórkę, a środek zostaje surowy, i krój dopiero, gdy ciasto całkiem wystygnie, inaczej spirala się rozpada.

W Niemczech wcześniejszy dzień pieczenia często ratuje 24 grudnia: zapach świeżo pieczonego makowca unosi się po domu już 23 grudnia, a w sam dzień świąt zostaje tylko podanie na stół. Gotowy makowiec ze sklepu bywa dla wielu rodzin ratunkiem w gorączce przygotowań, a nie zamiennikiem własnej techniki, co dokładnie opisuje [technika makowca](/pl/blog/makowiec-technika). Dzieci mogą pomagać przy mieszaniu masy makowej i smarowaniu jajkiem, zwijanie rolady i gorący piekarnik zostają przy dorosłych.

## Przy stole

Podawaj makowiec w plastrach, często oprószony cukrem pudrem, klasycznie jako słodkie zakończenie po klarownym [barszczu](/pl/rezepte/barszcz-czerwony) z [uszkami](/pl/rezepte/uszka). Upieczony dzień wcześniej wystarczy 24 grudnia tylko pokroić, co odciąża i tak już pełen dzień. Kto chce postawić na stole dwa desery naraz, stawia makowiec obok kremowego [sernika](/pl/rezepte/sernik), bo oba ciasta się dobrze uzupełniają, jedno makowe i zbite, drugie kremowe i wilgotne.

Za sucha masa makowa źle się rozsmarowuje i pęka podczas zwijania, a za mokra rozmiękcza ciasto od wewnątrz. Za dużo mąki w cieście robi miękisz suchy i ciężki, zbyt gorący piekarnik przypala powierzchnię, zanim środek się dopiecze. Kto kroi za wcześnie, przygniata jeszcze ciepłą spiralę na płasko, dlatego warto uzbroić się w cierpliwość do pełnego wystudzenia. Przy nadziewaniu zawsze trzeba zostawić wolny brzeg, inaczej masa wypłynie bokiem podczas zwijania.

Z rodzynkami albo z cienkim lukrem charakter ciasta zmienia się tylko odrobinę, mniejsze rolady sprawdzają się dobrze, gdy na stole ma się zmieścić kilka rodzajów świątecznych wypieków. Zupełnie innym świątecznym wypiekiem są chrupiące [faworki](/pl/rezepte/faworki), których technikę opisuje [technika faworków](/pl/blog/faworki-technika). Kremowy [sernik](/pl/rezepte/sernik) zostaje mimo wspólnej roli świątecznej zupełnie innym daniem, podobnie jak drożdżowa [babka](/pl/rezepte/babka) i korzenny [piernik](/pl/rezepte/piernik). Kto woli mak w formie na łyżkę, znajdzie go w pszennej [kucji](/pl/rezepte/kutia).', 'Makowiec przepis | Rolada makowa | Alemniam', 'Makowiec krok po kroku, polska rolada makowa z podpowiedziami zakupowymi w Niemczech i miejscem w menu wigilijnym.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
